package com.amadeus.aud.libraries.checker.reports;

import com.amadeus.aud.libraries.checker.models.Message;
import java.io.IOException;
import java.util.Collection;

/** Reporter checks each message generated by checks. */
public interface Reporter extends AutoCloseable {
  /** Format and add messages to the output stream. */
  void addMessages(Collection<Message> messages) throws IOException;

  /** See {@link java.lang.AutoCloseable::close} */
  @Override
  void close() throws IOException;
}
